const { writeFileSync } = await import('node:fs');
const html = process.env.HTML;
const outPath = process.env.OUTPUT_PATH;
if (!html) throw new Error('Missing HTML input');
if (!outPath) throw new Error('Missing output_path');
const inputPath = '/tmp/input.html';
writeFileSync(inputPath, html);
globalThis.inputPath = inputPath;
globalThis.outputPath = outPath;

const mod = await import('topdf');
const fn = mod.default || mod;
await fn(globalThis.inputPath, globalThis.outputPath);
globalThis.resultPath = globalThis.outputPath;
